mapper.delete:
delete a from t_cruise_point_instance AS a,t_robot_inspection AS b
        where b.inspection_id = a.cruise_id
        AND b.robot_id = #{robotId, jdbcType=BIGINT}

mapper.select:
select
a.robot_id,
a.robot_code,
a.robot_name,
a.robot_status,
a.robot_type,
a.robot_ip,
a.robot_port,
a.light_ip,
a.light_port,
a.identity_manager,
a.identity_code,
a.lnferad_IP,
a.Inferad_Port,
a.Inferad_username,
a.Inferad_password,
a.phote_path,
a.create_by,
a.create_date,
a.update_by,
a.update_date,
a.robot_factory,
a.is_use,
a.commission_date,
a.up_region_id,
a.robot_position,
a.robot_source,
a.address,
a.building_user,
a.appearance_number,
a.defect_record,
a.repair_record,
a.exit_putInto_record,
a.remarks
from t_robot_info a
where 1 = 1
 and a.robot_id = #{robotId, jdbcType=BIGINT}
 and a.robot_code = #{robotCode, jdbcType=VARCHAR}
 and a.robot_name = #{robotName, jdbcType=VARCHAR}
 and a.robot_status = #{robotStatus, jdbcType=VARCHAR}
 and a.robot_type = #{robotType, jdbcType=INTEGER}
 and a.robot_ip = #{robotIp, jdbcType=VARCHAR}
 and a.robot_port = #{robotPort, jdbcType=INTEGER}
 and a.light_ip = #{lightIp, jdbcType=VARCHAR}
 and a.light_port = #{lightPort, jdbcType=VARCHAR}
 and a.identity_manager = #{identityManager, jdbcType=VARCHAR}
 and a.identity_code = #{identityCode, jdbcType=VARCHAR}
 and a.lnferad_IP = #{lnferadIp, jdbcType=VARCHAR}
 and a.Inferad_Port = #{inferadPort, jdbcType=INTEGER}
 and a.Inferad_username = #{inferadUsername, jdbcType=VARCHAR}
 and a.Inferad_password = #{inferadPassword, jdbcType=VARCHAR}
 and a.phote_path = #{photePath, jdbcType=VARCHAR}
 and a.create_by = #{createBy, jdbcType=VARCHAR}
 and a.create_date = #{createDate, jdbcType=TIMESTAMP}
 and a.update_by = #{updateBy, jdbcType=VARCHAR}
 and a.update_date = #{updateDate, jdbcType=TIMESTAMP}
and a.robot_factory = #{robotFactory, jdbcType=VARCHAR},
and a.is_use = #{isUse, jdbcType=VARCHAR},
and a.commission_date = #{commissionDate, jdbcType=TIMESTAMP},
and a.up_region_id = #{upRegionId, jdbcType=BIGINT},
and a.robot_position = #{robotPosition, jdbcType=VARCHAR},
and a.robot_source = #{robotSource, jdbcType=VARCHAR},
and a.address = #{address, jdbcType=VARCHAR},
and a.building_user = #{buildingUser, jdbcType=VARCHAR},
and a.appearance_number = #{appearanceNumber, jdbcType=VARCHAR},
and a.defect_record = #{defectRecord, jdbcType=VARCHAR},
and a.repair_record = #{repairRecord, jdbcType=VARCHAR},
and a.exit_putInto_record = #{exitPutIntoRecord, jdbcType=VARCHAR},
 and a.remarks = #{remarks, jdbcType=VARCHAR}

select
    a.dict_code
FROM t_dict_business a
where 1 = 1
and a.col_name = #{colName, jdbcType=VARCHAR}
and a.dict_note = #{dictNote, jdbcType=VARCHAR}

select robot_id from t_robot_info
where 1 = 1
 and robot_code = #{robotCode, jdbcType=VARCHAR}
